-- end-of-statement
CREATE UNIQUE INDEX uniq_users_external_id_active ON public.users USING btree (external_id) WHERE ((deleted_at IS NULL) AND (external_id <> ''::text))
-- end-of-statement
CREATE UNIQUE INDEX uniq_users_username_folded_active ON public.users USING btree (username_folded) WHERE (deleted_at IS NULL)
